import React, { useEffect, useState, useRef } from 'react';
import { Link, useLocation } from 'react-router-dom';
import ReviewCard from '../components/ReviewCard';
import { fetchReviews } from '../api/reviewApi';
import RouletteWheel from '../components/RouletteWheel';
import PostCard from '../components/PostCard';

function Home() {
  const [latest, setLatest] = useState([]);
  const [posts, setPosts] = useState([]);
  const authorRef = useRef();
  const textRef = useRef();
  const fileRef = useRef();

  useEffect(() => {
    const load = async () => {
      try {
        const res = await fetchReviews({ page: 1, limit: 3 });
        setLatest(res.data);
      } catch (err) {
        console.error('fetch reviews failed', err);
      }
    };
    load();
  }, []);

  const location = useLocation();
  const params = new URLSearchParams(location.search);
  const showReviews = params.get('view') === 'reviews';

  // load posts from localStorage
  useEffect(() => {
    try {
      const raw = localStorage.getItem('blog_posts');
      if (raw) setPosts(JSON.parse(raw));
    } catch (e) { setPosts([]); }
  }, []);

  const savePosts = (list) => {
    try { localStorage.setItem('blog_posts', JSON.stringify(list)); } catch (e) {}
  };

  const handleCreatePost = async (e) => {
    e.preventDefault();
    const author = authorRef.current?.value || '익명';
    const text = textRef.current?.value || '';
    const file = fileRef.current?.files?.[0];
    let image = null;
    if (file) {
      image = await new Promise((res) => {
        const fr = new FileReader();
        fr.onload = () => res(fr.result);
        fr.readAsDataURL(file);
      });
    }
    const newPost = { _id: 'p' + Date.now(), author, text, image, createdAt: new Date().toISOString(), likes: 0 };
    const next = [newPost, ...posts];
    setPosts(next);
    savePosts(next);
    // reset form
    if (authorRef.current) authorRef.current.value = '';
    if (textRef.current) textRef.current.value = '';
    if (fileRef.current) fileRef.current.value = '';
  };

  return (
    <div style={{ padding: 20 }}>
      <header style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
        <div>
          <h1 style={{ margin: 0 }}>✨ Review Community</h1>
          <p style={{ color: '#666' }}>실제 사람들이 쓰는 생생한 리뷰를 만나보세요.</p>
        </div>
        <div>
          <Link to="/coupons"><button style={{ padding: '10px 14px', borderRadius: 10, background: '#ff6b6b', color: '#fff', border: 'none' }}>룰렛 참여하기</button></Link>
        </div>
      </header>

      {/* 블로그 포스트 작성 섹션 */}
      <section style={{ marginTop: 24, marginBottom: 12 }}>
        <h2>새 게시물 작성</h2>
        <form onSubmit={handleCreatePost} style={{ display: 'grid', gridTemplateColumns: '1fr 120px', gap: 12, alignItems: 'start' }}>
          <div>
            <input ref={authorRef} placeholder="작성자 이름 (선택)" style={{ width: '100%', padding: 10, borderRadius: 8, border: '1px solid #ddd', marginBottom: 8 }} />
            <textarea ref={textRef} placeholder="무슨 생각을 공유하고 싶나요? (텍스트 입력)" style={{ width: '100%', minHeight: 100, padding: 10, borderRadius: 8, border: '1px solid #ddd' }} />
            <div style={{ marginTop: 8 }}>
              <input ref={fileRef} type="file" accept="image/*" />
            </div>
          </div>
          <div>
            <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
              <button type="submit" style={{ padding: '10px 14px', borderRadius: 10, background: '#ff6b6b', color: '#fff', border: 'none', cursor: 'pointer' }}>게시하기</button>
              <Link to="/feed"><button type="button" style={{ padding: '10px 14px', borderRadius: 10, background: '#eee', border: 'none', cursor: 'pointer' }}>리뷰 보러가기</button></Link>
            </div>
          </div>
        </form>
      </section>

      {/* 포스트 피드 */}
      <section style={{ marginTop: 18 }}>
        <h2>최신 게시물</h2>
        <div style={{ display: 'grid', gap: 16, gridTemplateColumns: 'repeat(auto-fit, minmax(320px, 1fr))', marginTop: 12 }}>
          {posts.length === 0 ? (
            <p style={{ color: '#999' }}>아직 게시물이 없습니다. 첫 게시물을 작성해보세요!</p>
          ) : (
            posts.map(p => <PostCard key={p._id} post={p} />)
          )}
        </div>
      </section>

      {/* 기존 최신 리뷰 섹션 (하단으로 이동) - 기본적으로는 숨김, 쿼리 ?view=reviews 로 표시 */}
      {showReviews && (
        <section style={{ marginTop: 28 }}>
          <h2>최신 리뷰</h2>
          {latest.length === 0 ? (
            <p style={{ color: '#999' }}>최신 리뷰가 없습니다.</p>
          ) : (
            latest.map(r => <ReviewCard key={r._id} id={r._id} username={r.author?.username || '익명'} title={r.title} text={r.text} images={r.images} createdAt={r.createdAt} likes={r.likes} />)
          )}
        </section>
      )}

      <section style={{ marginTop: 28 }}>
        <h2>룰렛</h2>
        <RouletteWheel />
      </section>
    </div>
  );
}

export default Home;
